#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"; WORK_ROOT="${WORK_ROOT:-$ROOT/../agentic-work}"; PORT=8000; DRY=0; TIMEOUT=120
prev=''; for a in "$@"; do case "$a" in --dry-run) DRY=1;; --work-root) :;; --work-root=*) WORK_ROOT="${a#*=}";; --port) :;; --port=*) PORT="${a#*=}";; --timeout) :;; --timeout=*) TIMEOUT="${a#*=}";; -h|--help) echo 'Usage: lambda_healthcheck.sh [--work-root DIR] [--port PORT] [--timeout SEC] [--dry-run]'; exit 0;; *) if [[ "$prev" == --work-root ]]; then WORK_ROOT="$a"; elif [[ "$prev" == --port ]]; then PORT="$a"; elif [[ "$prev" == --timeout ]]; then TIMEOUT="$a"; else echo "unknown argument: $a" >&2; exit 2; fi;; esac; prev="$a"; done
if ((DRY)); then echo "DRY-RUN: require process, models endpoint, normal completion, tool call, token metrics, GPU sample, and clean logs on localhost:$PORT."; exit 0; fi
command -v curl >/dev/null || { echo 'curl required' >&2; exit 1; }; manifest="$WORK_ROOT/artifacts/manifests/vllm_server.json"; [[ -f "$manifest" ]] || { echo "missing $manifest" >&2; exit 1; }; pid="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["pid"])' "$manifest")"; [[ -d "/proc/$pid" ]] || { echo 'vLLM process is not alive' >&2; exit 1; }; base="http://127.0.0.1:$PORT"; deadline=$((SECONDS+TIMEOUT)); models=''; until models="$(curl -fsS --max-time 5 "$base/v1/models")"; do ((SECONDS<deadline)) || { echo 'models endpoint timeout' >&2; exit 1; }; sleep 1; done; model="$(python3 -c 'import json,sys;print(json.load(sys.stdin)["data"][0]["id"])' <<<"$models")"; body='{"model":"'"$model"'","messages":[{"role":"user","content":"Reply READY."}],"max_tokens":8,"temperature":0}'; response="$(curl -fsS --max-time 60 -H 'Content-Type: application/json' -d "$body" "$base/v1/chat/completions")"; python3 -c 'import json,sys;d=json.loads(sys.stdin.read());assert d.get("choices") and "prompt_tokens" in d.get("usage",{}) and "completion_tokens" in d.get("usage",{}) and d.get("metrics"), "completion, token, or timing metrics absent";print("normal completion and timing metrics present")' <<<"$response"; tool='{"model":"'"$model"'","messages":[{"role":"user","content":"Call ping."}],"tools":[{"type":"function","function":{"name":"ping","description":"Return pong","parameters":{"type":"object","properties":{}}}}],"tool_choice":{"type":"function","function":{"name":"ping"}},"max_tokens":32,"temperature":0}'; tool_response="$(curl -fsS --max-time 60 -H 'Content-Type: application/json' -d "$tool" "$base/v1/chat/completions")"; python3 -c 'import json,sys;d=json.loads(sys.stdin.read());m=d.get("choices",[{}])[0].get("message",{});assert m.get("tool_calls"), "SWE-agent-style tool call did not parse";print("tool-call response parsed")' <<<"$tool_response"; command -v nvidia-smi >/dev/null || { echo 'nvidia-smi required' >&2; exit 1; }; mkdir -p "$WORK_ROOT/artifacts/manifests"; nvidia-smi --query-gpu=name,memory.used,utilization.gpu --format=csv,noheader >"$WORK_ROOT/artifacts/manifests/health_gpu_sample.csv"; log="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1])).get("log_path", ""))' "$manifest")"; [[ -z "$log" || ! -f "$log" ]] || ! grep -Eiq 'out of memory|cuda error|fatal|traceback' "$log" || { echo 'fatal/OOM found in server log' >&2; exit 1; }; echo "vLLM healthcheck passed: $model"
